  [T('Habit','Habit'),T('Security','Security'),T('Economic factors','Money matter'),T('Fear of the unknown','Fear of wetin you no know'),T('Selective information processing','Na only wetin you like you dey hear')].forEach((x,i)=>t_(G,160,130+i*50,x,{'text-anchor':'middle','font-size':13}));
  [T('Threat to expertise','Threat to expertise'),T('Group inertia','Group no wan move'),T('Limited focus of change','Change wey too small'),T('Threat to power relationships','Threat to power'),T('Threat to resource allocation','Threat to who dey control resources')].forEach((x,i)=>t_(G,440,130+i*50,x,{'text-anchor':'middle','font-size':13}));
  // 7: seven tactics
  const Hh=tab(s);tabs.push([Hh,7,8,true]);title(Hh,32,'Seven tactics for resistance','Seven tactic for resistance');
  const tac=[[T('Education and communication','Education and communication'),1],[T('Participation','Participation'),1],[T('Building support and commitment','Build support and commitment'),1],[T('Negotiation','Negotiation'),2],[T('Manipulation and cooptation','Manipulation and cooptation'),3],[T('Selecting people who accept change','Select people wey accept change'),2],[T('Coercion','Force'),3]];
  const tG=tac.map(([x,r],i)=>{const g=el('g',{},Hh);box(g,60,58+i*46,480,38,r===1?'var(--org-soft)':r===2?'var(--data-soft)':'var(--err-soft)','none',10);t_(g,80,82+i*46,`${i+1}. ${x}`,{'font-size':13.5,'font-weight':700});t_(g,520,82+i*46,r===1?T('low risk','risk small'):r===2?T('costly or slow','e cost or e slow'):T('may backfire','e fit backfire'),{'font-size':11,'text-anchor':'end',fill:'var(--muted)'});return g;});
