    const cf=H.seg(t,2,3);const ph=cf<.33?0:cf<.66?1:2;cT.textContent=T('Lewin’s three steps','Lewin three steps');H.set(stageMark,{x:50+ph*180});
    const melt=ph===0?H.es(cf,0,.3):ph===1?1:1-H.es(cf,.7,.95);const xpos=ph===0?150:ph===1?H.lerp(150,420,H.es(cf,.36,.62)):420;const ih=H.lerp(150,30,melt),iw=H.lerp(120,180,melt);
    H.set(ice,{x:xpos-iw/2,y:300-ih,width:iw,height:ih,opacity:1-melt*.4});H.set(puddle,{cx:xpos,cy:304,rx:iw*.6*melt,ry:10*melt});
    cN.textContent=ph===0?T('Unfreeze: raise driving forces, lower restraining forces','Unfreeze: increase di force wey dey push, reduce di one wey dey hold'):ph===1?T('Move: get through the change quickly; fast movers do better','Move: pass through di change quick; people wey move fast dey do better'):T('Refreeze: lock in the new state, or people drift back','Refreeze: lock di new way, or people go go back to old way');
    kG.forEach((g,i)=>H.op(g,H.es(t,3+i*.1,3.15+i*.1)));
    const ap=H.along([...aP,aP[0]],(H.seg(t,4,5)*1.3)%1);H.set(arD,{cx:ap[0],cy:ap[1]});
    tG.forEach((g,i)=>H.op(g,H.es(t,7+i*.1,7.15+i*.1)));
