    const ef=H.seg(t,5,6);const pts=[];let crossX=null;for(let i=0;i<=50;i++){const x=5*i/50;if(x>5*ef)break;const y=100+Math.max(0,x-.6)*36+Math.sin(x*3)*10;pts.push([sax.sx(x),sax.sy(y)]);}if(pts.length>1){H.set(sp,{d:H.path(pts)});const last=pts[pts.length-1];H.set(gain,{x:last[0]-8,y:last[1],width:16,height:Math.max(0,sax.sy(100)-last[1])});}
