function u33Sandbox(ctl,st){
  const s=H.svg(st,520,280);let sales=300000;const ro=H.readout(ctl);
  H.slider(ctl,{id:'u33s',label:T('This month’s sales','Sales for dis month'),min:0,max:800000,step:10000,value:300000,fmt:naira},v=>{sales=v;draw();});
  function draw(){s.innerHTML='';const p=[[T('10% commission only','Only 10% commission'),.1*sales,'var(--err)'],[T('10%, minimum ₦20,000','10%, minimum ₦20,000'),Math.max(20000,.1*sales),'var(--data)'],[T('₦20,000 + 5% of sales','₦20,000 + 5% of sales'),20000+.05*sales,'var(--org)']];
    const mx=Math.max(...p.map(x=>x[1]),1);p.forEach(([l,v,c],i)=>{const y=30+i*80;t_(s,20,y,l,{'font-size':13,'font-weight':700});el('rect',{x:20,y:y+10,width:460,height:30,rx:8,fill:'var(--sunk)'},s);el('rect',{x:20,y:y+10,width:460*v/Math.max(80000,mx),height:30,rx:8,fill:c},s);t_(s,490,y+31,naira(v),{'font-size':13,'font-weight':700,'text-anchor':'end'});});
    const best=p.reduce((a,b)=>b[1]>a[1]?b:a);ro.innerHTML=T(`At <b>${naira(sales)}</b> in sales, the best plan for the salesperson is <b>${best[0]}</b>.<br>The course’s examples: 10% commission; 10% with a ₦20,000 minimum guarantee; or ₦20,000 salary plus 5% of sales.`,`If sales reach <b>${naira(sales)}</b>, di plan wey good pass for di salesperson na <b>${best[0]}</b>.<br>Di course examples: 10% commission; 10% with ₦20,000 minimum; or ₦20,000 salary plus 5% of sales.`);}
  draw();
}
Course.add({id:'3.3',module:3,title:B('Incentives in an Organisation','Incentives for Organisation'),vizLabel:B('Three pay plans crossing, a stock option and a profit pool','Three pay plan wey dey cross, stock option and profit pool'),
  hook:{who:B('Kunle, sales manager','Kunle, sales manager'),text:B('Kunle’s best salesperson is leaving for a rival that pays the same salary but a bigger commission. Pay is not just a cost; it tells people what effort is worth.','Kunle best salesperson wan go join another company wey dey pay di same salary but bigger commission. Pay no be only cost; e dey tell people how much dia effort worth.')},
  objectives:[B('Define “incentive”','Explain wetin “incentive” mean'),B('Explain monetary and non-monetary incentives, intrinsic and extrinsic motivation','Explain money and non-money incentive, intrinsic and extrinsic motivation'),B('Describe individual and group incentive plans','Describe individual and group incentive plan'),B('Identify the role of incentives in an organisation','Identify di role of incentive for organisation')],
  steps:[
    {h:B('What an incentive is','Wetin incentive be'),t:B('<p>An incentive is something that motivates a person to act: a force that shapes behaviour. Employees may work as hard as possible, just hard enough to avoid a reprimand, or as little as possible (Griffin, 2002). Incentives aim to get maximum performance and keep the most productive people. Rewards also affect <b>trust</b> (Gordner, 2005); poor incentive packages hurt commitment and productivity (Dixit and Bhati, 2012).</p>','<p>Incentive na something wey dey push person to act: force wey dey shape behaviour. Workers fit work as hard as dem fit, just reach make dem no query dem, or small-small as dem fit (Griffin, 2002). Incentive wan get di best performance and keep di people wey dey produce pass. Reward still dey affect <b>trust</b> (Gordner, 2005); bad incentive package dey spoil commitment and productivity (Dixit and Bhati, 2012).</p>'),say:B('An incentive is the carrot that makes extra effort worth it. (Note: the course cites Kohn as showing incentives produce superior work, but Kohn is best known for arguing the opposite, that rewards can undermine motivation.)','Incentive na di carrot wey dey make extra effort worth am. (Note: di course talk say Kohn show say incentive dey bring better work, but Kohn popular for di opposite argument, say reward fit spoil motivation.)')},
    {h:B('Monetary and non-monetary','Money and non-money'),t:B('<p>Luthans splits incentives into <b>monetary</b> (salary, insurance, profit sharing, retirement plans, stock, overtime, attendance and safety incentives, contests, merit increases, bonuses, suggestion awards) and <b>non-monetary</b> (more authority, awards, a say in management, promotion, holidays, better working conditions, written recognition, gifts, dinners, parties, plaques).</p>','<p>Luthans divide incentive into <b>money</b> (salary, insurance, profit sharing, pension, share, overtime, attendance and safety incentive, contest, merit increase, bonus, award for suggestion) and <b>no be money</b> (more power, award, voice for management, promotion, holiday, better work condition, letter of praise, gift, dinner, party, plaque).</p>')},
    {h:B('Intrinsic and extrinsic','Intrinsic and extrinsic'),t:B('<p><b>Intrinsic</b> motivation comes from inside: needs for competence and autonomy, interesting work, using your ability, achievement, development and being treated with care. <b>Extrinsic</b> motivation comes from outside: money, grades, prizes.</p>','<p><b>Intrinsic</b> motivation dey come from inside: need for competence and freedom, work wey sweet, to use your ability, achievement, growth and to dey treated well. <b>Extrinsic</b> motivation dey come from outside: money, grades, prize.</p>'),say:B('Intrinsic: you play football because you love it. Extrinsic: you play because someone pays you.','Intrinsic: you dey play ball because you love am. Extrinsic: you dey play because person dey pay you.')},
    {h:B('Individual incentive plans','Individual incentive plan'),t:B('<p>Individual plans are over a century old: a strong iron loader on piece rates could earn 50% more a day than one on a basic day rate. Salespeople often earn commission, e.g. 10% of sales. Because pure commission is risky, many firms use a <b>guaranteed minimum</b> (10% with at least ₦20,000 a month) or a <b>salary plus commission</b> (₦20,000 plus 5%).</p>','<p>Individual plan don dey pass 100 years: strong iron loader wey dem dey pay per load fit earn 50% more for one day pass person wey dey collect basic day rate. Salespeople dey collect commission, like 10% of sales. Because pure commission get risk, many company dey use <b>minimum guarantee</b> (10% with at least ₦20,000 every month) or <b>salary plus commission</b> (₦20,000 plus 5%).</p>')},
    {h:B('Comparing the three plans','Compare di three plan'),t:B('<p>The guarantee protects the salesperson in bad months; the base-plus-5% plan pays more at low sales but less at high sales. All three pay ₦40,000 at ₦400,000 of sales; beyond that, straight 10% commission pays most.</p>','<p>Di guarantee dey protect di salesperson for bad month; di base-plus-5% plan dey pay more when sales small but e dey pay less when sales big. All three dey pay ₦40,000 when sales reach ₦400,000; after dat, straight 10% commission dey pay pass.</p>')},
    {h:B('Bonuses and stock options','Bonus and stock option'),t:B('<p><b>Bonuses</b>: signing bonuses for athletes, footballers and managers; in uncertain economies firms shift to performance-based bonuses rather than fixed raises. <b>Stock options</b>, usually for senior managers, give the right to buy company shares later at a fixed price; if they raise performance, the share price, and their reward, rises.</p>','<p><b>Bonus</b>: signing bonus for athletes, footballers and managers; when economy no sure, company dey move to bonus wey follow performance instead of fixed increase. <b>Stock option</b>, mostly for senior managers, dey give right to buy company share later for fixed price; if dem push performance up, share price, and dia reward, go rise.</p>')},
    {h:B('Group incentive plans','Group incentive plan'),t:B('<p>Teams can beat individuals, so group pay is growing. <b>Gain-sharing</b> shares net gains from productivity improvements with the team. <b>Profit-sharing</b> pays part of profits into a pool for all employees, immediately, at year end, or deferred until retirement. Research on profit-sharing is inconclusive, though engineers who viewed it favourably showed more commitment (Hart and Quinn, 1993).</p>','<p>Team fit perform pass individual, so group pay dey grow. <b>Gain-sharing</b> dey share di gain from productivity with di team. <b>Profit-sharing</b> dey put part of profit for pool for all workers, immediately, end of year, or for retirement. Research for profit-sharing never conclude, but engineers wey like am show more commitment (Hart and Quinn, 1993).</p>')}
  ],
  scene:u33Scene,
  words:[[B('Incentive','Incentive'),B('A reward that encourages people to do more or better.','Reward wey dey encourage people make dem do more or better.')],[B('Commission','Commission'),B('Pay based on a percentage of what you sell.','Pay wey dey follow percentage of wetin you sell.')],[B('Intrinsic motivation','Intrinsic motivation'),B('Drive that comes from inside: interest, pride, growth.','Push wey dey come from inside: interest, pride, growth.')],[B('Extrinsic motivation','Extrinsic motivation'),B('Drive that comes from outside rewards like money.','Push wey dey come from outside reward like money.')],[B('Stock option','Stock option'),B('The right to buy company shares later at a fixed price.','Right to buy company share later for fixed price.')],[B('Gain-sharing','Gain-sharing'),B('Sharing savings from better productivity with the team.','To share di money wey better productivity save with di team.')]],
  sandboxIntro:B('Slide the month’s sales and compare what a salesperson earns under the course’s three pay plans.','Shift di month sales and compare wetin salesperson go earn for di course three pay plan.'),
  sandbox:u33Sandbox,
  sae:{q:B('(1) How prevalent are intrinsic incentives in organisations today? (2) Differentiate between extrinsic and intrinsic incentives.','(1) How common intrinsic incentive be for organisation today? (2) Show di difference between extrinsic and intrinsic incentive.'),a:B('Intrinsic incentives (interesting work, recognition, development, participation, being treated with care) are widely used because they cost little and build commitment, especially for knowledge workers. Extrinsic incentives come from outside the person (money, prizes, grades); intrinsic ones come from inside (competence, autonomy, achievement).','Intrinsic incentive (work wey sweet, recognition, growth, participation, to dey treated well) common because dem no cost much and dem dey build commitment, mostly for knowledge workers. Extrinsic dey come from outside di person (money, prize, grades); intrinsic dey come from inside (competence, freedom, achievement).')},
  tma:{q:B('Explain the meaning of incentive and name five of its benefits to an organisation.','Explain wetin incentive mean and name five of im benefit to organisation.'),outline:[B('Definition (Griffin; Arnold; Luthans’ split)','Definition (Griffin; Arnold; Luthans split)'),B('Benefits: higher performance, retention of the best, commitment, trust, productivity','Benefit: better performance, keep di best people, commitment, trust, productivity'),B('Lower turnover intention','Reduce people wey wan leave'),B('Better attitude to work','Better attitude to work'),B('Examples of individual and group plans','Example of individual and group plan')]},
  quiz:[
    {q:B('Under ₦20,000 + 5%, what does a salesperson earn on ₦300,000 of sales?','For ₦20,000 + 5%, how much salesperson go earn if sales na ₦300,000?'),o:['₦30,000','₦35,000','₦20,000','₦15,000'],a:1,w:B('₦20,000 + 5% × ₦300,000 = ₦20,000 + ₦15,000 = ₦35,000.','₦20,000 + 5% × ₦300,000 = ₦20,000 + ₦15,000 = ₦35,000.')},
    {q:B('A promotion is which kind of incentive?','Promotion na which kind incentive?'),o:[B('Monetary','Money'),B('Non-monetary','No be money'),B('Gain-sharing','Gain-sharing'),B('Stock option','Stock option')],a:1,w:B('Promotion, holidays and recognition are non-monetary.','Promotion, holiday and recognition no be money.')},
    {q:B('Profit-sharing is a…','Profit-sharing na…'),o:[B('Group incentive','Group incentive'),B('Individual commission','Individual commission'),B('Fine','Fine'),B('Non-monetary reward','Reward wey no be money')],a:0,w:B('Part of profits goes into a pool for all employees.','Part of profit dey go pool for all workers.')},
    {q:B('Intrinsic motivation arises from…','Intrinsic motivation dey come from…'),o:[B('Money and prizes','Money and prize'),B('Inside the person: competence and autonomy','Inside di person: competence and freedom'),B('Threats','Threat'),B('Customers','Customers')],a:1,w:B('Extrinsic motivation comes from outside rewards.','Extrinsic motivation dey come from outside reward.')}
  ],
  card:[{h:B('Types of incentive','Types of incentive'),items:[B('Monetary (financial)','Money (financial)'),B('Non-monetary (non-financial)','No be money (non-financial)')]},{h:B('Individual plans','Individual plan'),items:[B('Piece rate / commission','Piece rate / commission'),B('Guaranteed minimum plus commission','Minimum guarantee plus commission'),B('Salary plus commission','Salary plus commission'),B('Bonuses','Bonus'),B('Stock options','Stock option')]},{h:B('Group plans','Group plan'),items:[B('Gain-sharing','Gain-sharing'),B('Profit-sharing','Profit-sharing')]}]
});

