function u34Sandbox(ctl,st){
  const jobs=[[T('Bank cashier','Bank cashier'),'con'],[T('Delivery-schedule clerk who phones customers','Clerk wey dey call customers for delivery schedule'),'mod'],[T('Product designer','Product designer'),'inf'],[T('Payroll officer','Payroll officer'),'sol'],[T('Restaurant waiter','Restaurant waiter'),'con'],[T('Pricing manager','Pricing manager'),'inf'],[T('Server-room IT technician','IT technician for server room'),'sol'],[T('Billing clerk who answers letters','Billing clerk wey dey answer letter'),'mod']];
  const ans=jobs.map(()=>null);const ro=H.readout(ctl);const s=H.svg(st,520,300);
  jobs.forEach(([n],i)=>H.segBtns(ctl,n,EMP.map(e=>[e[0],Course.L(e[1])]),null,v=>{ans[i]=v;draw();}));
  function draw(){s.innerHTML='';EMP.forEach(([k,n],c)=>{const x=10+c*128;box(s,x,10,120,280,['var(--emp-soft)','var(--data-soft)','var(--org-soft)','var(--sunk)'][c],'none',12);t_(s,x+60,34,Course.L(n),{'text-anchor':'middle','font-size':12.5,'font-weight':700});});
    const cnt={};let right=0,done=0;jobs.forEach(([n,k],i)=>{if(!ans[i])return;done++;const ok=ans[i]===k;if(ok)right++;const c=EMP.findIndex(e=>e[0]===ans[i]);cnt[c]=(cnt[c]||0);const y=52+cnt[c]*56;cnt[c]++;box(s,14+c*128,y,112,48,ok?'var(--card)':'var(--err-soft)',ok?'var(--line)':'var(--err)',8);wrap(s,70+c*128,y+18,n+(ok?' ✓':' ✗'),16,{'text-anchor':'middle','font-size':10,'font-weight':700,lh:12});});
    ro.innerHTML=T(`Placed <b>${done}</b> of ${jobs.length}; <b>${right}</b> match the course’s definitions.`,`You don place <b>${done}</b> out of ${jobs.length}; <b>${right}</b> match di course definition.`)+(done===jobs.length&&right<jobs.length?T('<br>Hint: modifiers contact customers, just less often and not face to face.','<br>Hint: modifiers dey contact customers, but no be often and no be face to face.'):'');}
  draw();H.tag(st,T('Example jobs are ours; the four categories are the course’s','Na we choose di example jobs; di four category na from di course'));
}
Course.add({id:'3.4',module:3,title:B('Internal Marketing in Organisations','Internal Marketing for Organisation'),vizLabel:B('Staff at the centre, rippling out to customers','Staff for di centre, e dey spread reach customers'),
  hook:{who:B('Zainab, hotel GM','Zainab, hotel GM'),text:B('Zainab’s hotel launched a glossy “we put guests first” advert. The housekeepers only heard about it when guests quoted it to them. Can staff deliver a promise nobody sold to them first?','Zainab hotel launch fine advert wey talk say “guest na number one”. Housekeepers only hear about am when guests quote am give dem. Staff fit deliver promise wey nobody first sell give dem?')},
  objectives:[B('State the meaning of internal marketing','Talk wetin internal marketing mean'),B('Describe how an internal marketing plan is developed and implemented','Describe how dem dey build and run internal marketing plan'),B('Outline the tactical steps','List di tactical steps'),B('Explain managerial and employee influences, and the benefits','Explain how managers and workers dey influence am, and di benefit')],
  steps:[
    {h:B('Inside before outside','Inside before outside'),t:B('<p>Marketing usually faces outwards to customers. But because employees’ attitudes shape how customers judge service quality, an organisation must first <b>win the hearts and minds of its employees</b>. Internal marketing must come ahead of external marketing (Kotler and Armstrong, 1999).</p>','<p>Marketing dey usually face outside to customers. But because workers’ attitude dey shape how customers go judge service quality, organisation must first <b>win di heart and mind of im workers</b>. Internal marketing must come before external marketing (Kotler and Armstrong, 1999).</p>'),say:B('If your staff don’t believe the advert, your customers won’t either.','If your staff no believe di advert, your customers no go believe am too.')},
    {h:B('Four definitions','Four definition'),t:B('<p><b>Varey</b>: marketing in the internal environment. <b>Rafiq and Ahmed</b>: a planned, market-like effort to overcome resistance and motivate customer-oriented staff. <b>Lancaster et al.</b>: focusing staff on internal changes the market needs. <b>Kotler and Keller</b>: hiring, training and motivating able employees who want to serve customers well, with vertical and horizontal alignment.</p>','<p><b>Varey</b>: marketing inside di organisation. <b>Rafiq and Ahmed</b>: planned effort wey be like market to beat resistance and motivate staff wey dey think customer. <b>Lancaster et al.</b>: to focus staff on inside change wey market need. <b>Kotler and Keller</b>: to hire, train and motivate workers wey sabi and wan serve customers well, align up and align sideways.</p>')},
    {h:B('Building the plan','How to build di plan'),t:B('<p>Create persuasive, informative messages for every department. Customers judge the whole experience, not just the product. Use <b>market research</b> on staff needs, <b>communications</b> that also listen and approve suggestions, and <b>distribution</b> through meetings and workshops, though culture and processes carry the message most powerfully.</p>','<p>Create message wey dey persuade and inform for every department. Customers dey judge di whole experience, no be only di product. Use <b>market research</b> on wetin staff need, <b>communication</b> wey still dey listen and approve suggestion, and <b>distribution</b> through meeting and workshop, but culture and process na im dey carry di message pass.</p>')},
    {h:B('Managers’ role','Managers’ role'),t:B('<p>Top-down management is only a temporary fix. Knowledge is spread among employees, customers, suppliers and communities, so organisations need <b>bottom-up, side-to-side and top-down</b> communication. Managers design the internal market’s infrastructure, set policies, resolve conflict, share knowledge, build alliances and inspire.</p>','<p>Management from top go down na temporary solution. Knowledge dey with workers, customers, suppliers and community, so organisation need communication wey dey go <b>bottom go up, side to side and top go down</b>. Managers dey design di internal market, set policy, settle wahala, share knowledge, build alliance and inspire.</p>')},
    {h:B('Four kinds of employee','Four kind worker'),t:B('<p>Employees are <b>internal customers</b>. By contact with external customers they are <b>contactors</b> (frequent, direct), <b>modifiers</b> (less frequent, usually not face to face), <b>influencers</b> (no direct contact but decisions affect customers) and <b>solitaries</b> (isolated from customers). Contactors depend on support from the rest, so all must be service-minded.</p>','<p>Workers na <b>internal customers</b>. By how dem dey meet outside customers, dem be <b>contactors</b> (dem dey meet often, face to face), <b>modifiers</b> (no be often, mostly no be face to face), <b>influencers</b> (dem no dey meet customers but dia decision dey affect customers) and <b>solitaries</b> (dem no get anything to do with customers). Contactors depend on support from di rest, so everybody must dey think service.</p>')},
    {h:B('Tactics and benefits','Tactic and benefit'),t:B('<p>Tactics: map every customer contact point, let top performers give feedback, use newsletters, radio, blogs and wikis, build marketing into training, share information often, use performance incentives, train at all levels, tell a brand story, tailor messages per department, celebrate wins, encourage collaboration. Benefits: better performance everywhere, shared goals, valued staff, higher morale, a marketing mind in non-marketers, retention, cooperation and clearer expectations.</p>','<p>Tactic: map every place wey una dey meet customer, make di best workers give feedback, use newsletter, radio, blog and wiki, put marketing inside training, share information often, use performance incentive, train for all level, tell brand story, change message for each department, celebrate wins, encourage collaboration. Benefit: better performance everywhere, everybody understand di goal, staff feel say dem dey valued, morale high, people wey no be marketer go dey think marketing, customers go stay, cooperation, and expectation go clear.</p>')}
  ],
  scene:u34Scene,
  words:[[B('Internal marketing','Internal marketing'),B('Treating staff as customers you must win over first.','To treat staff like customers wey you must first win.')],[B('Internal customer','Internal customer'),B('A colleague who relies on your work.','Colleague wey dey depend on your work.')],[B('Contactor','Contactor'),B('A worker who deals with customers often and directly.','Worker wey dey deal with customers often and face to face.')],[B('Solitary','Solitary'),B('A worker with no customer contact.','Worker wey no dey meet customer at all.')],[B('Alignment','Alignment'),B('Everyone pulling in the same direction.','Everybody dey pull for di same direction.')]],
  sandboxIntro:B('Sort each job into the course’s four categories of employee.','Put each job for di course four kind of worker.'),
  sandbox:u34Sandbox,
  sae:{q:B('Why must internal marketing come before external marketing?','Why internal marketing must come before external marketing?'),a:B('Customers judge the whole experience, and employees deliver it. If staff do not understand or believe the firm’s promise, they cannot keep it, so the external campaign fails. Winning staff first creates motivated, customer-minded employees who deliver what the advertising promises.','Customers dey judge di whole experience, and na workers dey deliver am. If staff no understand or believe di company promise, dem no fit keep am, so di external campaign go fail. To first win staff go create workers wey dey motivated and dey think customer, wey go deliver wetin di advert promise.')},saeOwn:true,
  tma:{q:B('(1) Define internal marketing according to two authors. (2) Outline the tactical steps in internal marketing. (3) State five ways internal marketing benefits organisations.','(1) Explain internal marketing as two authors talk am. (2) List di tactical steps for internal marketing. (3) Talk five ways internal marketing dey help organisation.'),outline:[B('Two definitions, e.g. Varey; Kotler and Keller','Two definition, like Varey; Kotler and Keller'),B('List the tactical steps with short explanations','List di tactical steps with short explanation'),B('Five benefits (morale, shared goals, coordination, information flow, retention)','Five benefit (morale, shared goal, coordination, information flow, retention)'),B('Mention the four employee categories','Mention di four kind of worker'),B('Conclude: excel internally to excel externally','End: do well inside to do well outside')]},
  quiz:[
    {q:B('Employees who have no direct customer contact but make decisions that affect customers are…','Workers wey no dey meet customers but dia decision dey affect customers na…'),o:[B('Contactors','Contactors'),B('Modifiers','Modifiers'),B('Influencers','Influencers'),B('Solitaries','Solitaries')],a:2,w:B('Solitaries are isolated from customers altogether.','Solitaries no get anything to do with customers.')},
    {q:B('The most potent way to distribute the internal message is through…','Di strongest way to spread di internal message na through…'),o:[B('Posters','Poster'),B('Culture and processes','Culture and process'),B('Fines','Fine'),B('External adverts','Outside advert')],a:1,w:B('Meetings help, but culture and processes carry it most powerfully.','Meeting dey help, but culture and process dey carry am pass.')},
    {q:B('Kotler and Keller say internal marketing needs…','Kotler and Keller talk say internal marketing need…'),o:[B('Only vertical alignment','Only align up'),B('Vertical and horizontal alignment','Align up and align sideways'),B('No alignment','No alignment'),B('Only advertising','Only advertising')],a:1,w:B('With senior management and with other departments.','With top management and with other department.')}
  ],
  card:[{h:B('Employee categories','Kind of worker'),items:EMP.map(e=>e[1])},{h:B('Benefits of internal marketing','Benefit of internal marketing'),items:[B('Better performance in every department','Better performance for every department'),B('Common understanding of goals','Everybody understand di goal'),B('Values staff contribution','E dey value staff contribution'),B('Higher morale and motivation','Morale and motivation high'),B('Marketing focus for non-marketing staff','People wey no be marketer go dey think marketing'),B('Better development and customer retention','Better growth and customers go stay'),B('Effective coordination and information flow','Coordination and information flow well')]}]
});

